def transform(grid):
    n = len(grid)
    # Each colored anti-diagonal gives the color for its sum modulo the
    # smallest repeating period supported by the observed diagonals.
    by_sum = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                by_sum.setdefault(r + c, v)

    period = 1
    for p in range(1, 2 * n):
        if all(by_sum[a] == by_sum[b]
               for a in by_sum for b in by_sum
               if a % p == b % p):
            period = p
            break

    colors = {}
    for s, v in by_sum.items():
        colors[s % period] = v

    # Fill unresolved residues by repeating the observed diagonal-color pattern.
    known = sorted(colors)
    out = []
    for r in range(n):
        row = []
        for c in range(n):
            k = (r + c) % period
            if k not in colors:
                k = min(known, key=lambda x: min((x-k) % period, (k-x) % period))
            row.append(colors[k])
        out.append(row)
    return out
